const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z',feather:'M20 4c-5-5-11 1-12 4L4 20l12-4c3-1 9-7 4-12ZM4 20 17 7M9 15h5m-2-5v5',leaf:'M20 3C9 2 2 8 6 16s15 2 14-13ZM4 21 16 9',paw:'M12 11c-2 0-3 2-4 3-5 4-1 7 4 5 5 2 9-1 4-5-1-1-2-3-4-3ZM7 8a2 3 0 1 0-4 0 2 3 0 1 0 4 0Zm5-3a2 3 0 1 0-4 0 2 3 0 1 0 4 0Zm5 0a2 3 0 1 0-4 0 2 3 0 1 0 4 0Zm4 3a2 3 0 1 0-4 0 2 3 0 1 0 4 0Z',bookmark:'M6 3h12v18l-6-4-6 4z',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 11v6m0-10v.1',arrow:'M5 19 19 5M7 5h12v12','zoom-in':'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6M7 10h6m-3-3v6','zoom-out':'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6M7 10h6',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',reset:'M3 10a9 9 0 1 1 1 8M3 4v6h6',drag:'M3 12h18M7 8l-4 4 4 4m10-8 4 4-4 4','rotate-left':'M7 5 3 9l4 4M3 9h11a6 6 0 0 1 0 12','rotate-right':'m17 5 4 4-4 4M21 9H10a6 6 0 0 0 0 12',pause:'M8 5v14M16 5v14',play:'m7 4 14 8-14 8z',trees:'m8 3-5 8h3l-4 6h5v4m1-18 5 8h-3l4 6H9m9-14-3 6h2l-3 5h7l-3-5h2zM18 14v7',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z',ruler:'m4 15 11-11 5 5L9 20zM9 10l2 2m2-6 2 2m-10 6 2 2',wings:'M12 15c-2-6-5-9-10-8 0 4 4 8 10 8Zm0 0c2-6 5-9 10-8 0 4-4 8-10 8Z',diet:'M21 12c-4-6-11-6-16 0 5 6 12 6 16 0ZM5 12l-3-4v8zM16 12h.1'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`}
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}icons();
const species=[{id:'toucan',name:'Keel-billed toucan',short:'Toucan',display:'Keel-billed<br>toucan',latin:'Ramphastos sulfuratus',family:'RAMPHASTIDAE',group:'bird',tags:['Canopy dweller','Fruit eater','Social'],description:'A rainbow in the treetops. With its bright, lightweight bill and sun-yellow throat, the keel-billed toucan is one of the rainforest’s most striking residents. It travels in small groups, passing fruit between branches and helping the forest grow with every seed it disperses.',traits:[['ruler','Length','42–55 cm'],['wings','Bill','12–15 cm'],['diet','Diet','Fruit, insects & small prey'],['globe','Range','Central & South America']],habitat:'Humid tropical forests, from the understory to the canopy.',range:'Central & South America',status:'Near threatened',code:'NT',closeup:'A bill as remarkable as the bird.',factory:()=>bird(false)}, {id:'macaw',name:'Scarlet macaw',short:'Macaw',display:'Scarlet<br>macaw',latin:'Ara macao',family:'PSITTACIDAE',group:'bird',tags:['Canopy dweller','Seed eater','Pair bonded'],description:'Scarlet, gold, and a sweep of blue. The scarlet macaw brings unmistakable color to the forest canopy. Its powerful curved bill opens tough nuts and seeds, while long tail feathers help guide its flight between the treetops.',traits:[['ruler','Length','81–96 cm'],['wings','Wingspan','About 1 m'],['diet','Diet','Fruit, nuts & seeds'],['globe','Range','Central & South America']],habitat:'Lowland tropical rainforest and wooded river corridors.',range:'Central & South America',status:'Least concern',code:'LC',closeup:'Layer upon layer of vivid flight feathers.',factory:()=>bird(true)}, {id:'frog',name:'Red-eyed tree frog',short:'Tree frog',display:'Red-eyed<br>tree frog',latin:'Agalychnis callidryas',family:'HYLIDAE',group:'amphibian',tags:['Nocturnal','Tree dweller','Insect eater'],description:'A tiny jewel hiding beneath a leaf. By day, this tree frog folds its bright orange toes and closes its brilliant red eyes. At night it wakes to hunt, gripping the leaves with adhesive toe pads as it moves through the forest.',traits:[['ruler','Length','4–7 cm'],['leaf','Active','At night'],['diet','Diet','Insects'],['globe','Range','Central America']],habitat:'Leaves and branches in humid lowland forests, near water.',range:'Central America',status:'Least concern',code:'LC',closeup:'Brilliant eyes and delicate adhesive toes.',factory:frog}, {id:'jaguar',name:'Jaguar',short:'Jaguar',display:'Jaguar',latin:'Panthera onca',family:'FELIDAE',group:'mammal',tags:['Forest floor','Carnivore','Solitary'],description:'Quiet power in the dappled light. The Americas’ largest wild cat moves through the rainforest with a rosette-patterned coat that blends into the shadows. An accomplished swimmer, the jaguar is equally at home beside rivers and in dense forest.',traits:[['ruler','Body length','1.1–1.8 m'],['paw','Behavior','Mostly solitary'],['diet','Diet','Mammals, reptiles & fish'],['globe','Range','Central & South America']],habitat:'Dense tropical forests, wetlands, and wooded riverbanks.',range:'Central & South America',status:'Near threatened',code:'NT',closeup:'Rosettes that disappear into forest light.',factory:jaguar}];
let selected=0,filter='featured',query='',paused=matchMedia('(prefers-reduced-motion: reduce)').matches,orbit=false,closeup=false,evening=false,saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('canopy-saved')||'[]'))}catch{}
let renderer,scene,camera,model,keyLight,fillLight,shadow,sceneReady=false,visible=true;let yaw=-.15,pitch=0,distance=10.8,targetDistance=10.8,focus=new T.Vector3(0,-.06,0),targetFocus=focus.clone(),previousTime=0;
const thumbnails=new Map(),details=new Map();
function disposeModel(obj){const geometries=new Set(),materials=new Set();obj.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])materials.add(m)}});geometries.forEach(g=>g.dispose());materials.forEach(m=>{if(!m.map)m.dispose()})}
function lighting(s){s.add(new T.HemisphereLight('#fffbe7','#789068',2.5));const a=new T.DirectionalLight('#fff4d6',3.2);a.position.set(4,7,5);s.add(a);const b=new T.DirectionalLight('#e2f4fa',1.7);b.position.set(-3,4,-4);s.add(b);return[a,b]}
function generateThumbnails(){const c=document.createElement('canvas'),r=new T.WebGLRenderer({canvas:c,alpha:true,antialias:true,preserveDrawingBuffer:true});r.setSize(300,200);r.setPixelRatio(1);r.outputColorSpace=T.SRGBColorSpace;r.toneMapping=T.ACESFilmicToneMapping;const s=new T.Scene();lighting(s);const cam=new T.PerspectiveCamera(33,1.5,.1,100);for(const sp of species){const obj=sp.factory();s.add(obj);cam.position.set(sp.group==='bird'?3.3:2,sp.group==='bird'?3:1.5,sp.group==='bird'?6.3:6.9);cam.lookAt(0,-.08,0);r.render(s,cam);thumbnails.set(sp.id,c.toDataURL('image/png'));const head=obj.userData.head||new T.Vector3(sp.id==='frog'?0:.83,.3,.4);cam.position.copy(head).add(new T.Vector3(1.7,.6,2.8));cam.lookAt(head);r.render(s,cam);details.set(sp.id,c.toDataURL('image/png'));s.remove(obj);disposeModel(obj)}r.dispose();$('featured-preview').innerHTML=`<img src="${thumbnails.get('toucan')}" alt="Flying keel-billed toucan">`}
function makeShadow(){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d'),grad=ctx.createRadialGradient(64,64,0,64,64,64);grad.addColorStop(0,'rgba(62,79,41,.14)');grad.addColorStop(.4,'rgba(62,79,41,.07)');grad.addColorStop(1,'rgba(62,79,41,0)');ctx.fillStyle=grad;ctx.fillRect(0,0,128,128);const m=new T.Mesh(new T.PlaneGeometry(5,3),new T.MeshBasicMaterial({map:new T.CanvasTexture(c),transparent:true,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.y=-1.1;scene.add(m);return m}
function cameraPosition(){const s=species[selected],head=closeup&&model?model.userData.head||new T.Vector3(s.id==='frog'?0:.83,.3,.4):new T.Vector3(0,-.06,0);targetFocus.copy(head);const elevation=(s.group==='bird'?.60:.15)+pitch;camera.position.set(focus.x+Math.sin(yaw+.50)*Math.cos(elevation)*distance,focus.y+Math.sin(elevation)*distance,focus.z+Math.cos(yaw+.50)*Math.cos(elevation)*distance);camera.lookAt(focus)}
function resize(){if(!sceneReady)return;const rect=$('stage').getBoundingClientRect();renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix();cameraPosition();renderer.render(scene,camera)}
function initScene(){renderer=new T.WebGLRenderer({canvas:$('scene'),alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;scene=new T.Scene();camera=new T.PerspectiveCamera(34,1,.1,100);[keyLight,fillLight]=lighting(scene);shadow=makeShadow();model=species[0].factory();scene.add(model);sceneReady=true;new ResizeObserver(resize).observe($('stage'));resize();generateThumbnails();requestAnimationFrame(animate)}
function animate(time){const dt=Math.min((time-previousTime)/1000,.06)||.016;previousTime=time;if(visible&&sceneReady){if(orbit)yaw+=dt*.25;distance=T.MathUtils.lerp(distance,targetDistance,paused?1:.10);focus.lerp(targetFocus,paused?1:.10);if(model){if(!paused){const t=time*.001;model.position.y=Math.sin(t*1.25)*.065;model.rotation.z=model.userData.isBird?Math.sin(t*.7)*.035:0;for(const [i,w]of(model.userData.wings||[]).entries()){w.rotation.x=(i===0?1:-1)*(.06+Math.sin(t*2.15)*.12);w.rotation.z=Math.sin(t*2.15)*.045}}cameraPosition();renderer.render(scene,camera)}}requestAnimationFrame(animate)}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function filteredSpecies(){return species.map((s,i)=>({s,i})).filter(({s})=>{const groupMatches=filter==='all'||filter==='featured'||filter===s.group||(filter==='saved'&&saved.has(s.id));const text=[s.name,s.latin,s.group,s.habitat,s.range,...s.tags].join(' ').toLowerCase();return groupMatches&&text.includes(query.toLowerCase())})}
function renderTabs(){const list=filteredSpecies();$('species-tabs').innerHTML=list.map(({s,i})=>`<button class="species-tab ${i===selected?'selected':''}" data-species="${i}" aria-label="Select ${s.name}" aria-pressed="${i===selected}"><span class="tab-image">${thumbnails.has(s.id)?`<img src="${thumbnails.get(s.id)}" alt="">`:''}</span><strong>${s.short}</strong><i>${s.latin}</i>${saved.has(s.id)?'<span class="tab-saved" aria-label="Saved">♡</span>':''}</button>`).join('');$('empty-state').hidden=list.length>0;$('empty-state').textContent=filter==='saved'&&!query?'Your collection is waiting. Save a species with the bookmark button.':'No species found. Try another search.';document.querySelectorAll('[data-species]').forEach(b=>b.onclick=()=>selectSpecies(Number(b.dataset.species)));$('mobile-count').textContent=`${selected+1} / ${species.length}`}
function updateSaved(){const is=saved.has(species[selected].id);$('save').setAttribute('aria-pressed',is);$('save').setAttribute('aria-label',is?'Remove species from collection':'Save species');$('collection-count').textContent=`${saved.size} saved`}
function selectSpecies(i){selected=i;const s=species[i];closeup=false;$('view-badge').hidden=true;targetDistance=s.group==='bird'?10.8:7.5;yaw=s.group==='bird'?-.15:s.id==='frog'?-.5:-.12;pitch=0;if(sceneReady){scene.remove(model);disposeModel(model);model=s.factory();scene.add(model);shadow.position.y=s.group==='bird'?-1.1:-1.2;shadow.scale.setScalar(s.group==='bird'?1:.8)}$('scene-name').textContent=s.name;$('scene-latin').textContent=s.latin;$('specimen-number').textContent=`SPECIMEN ${String(i+1).padStart(3,'0')}`;$('detail-name').innerHTML=s.display;$('detail-latin').textContent=s.latin;$('family').textContent=s.family;$('description').textContent=s.description;$('tags').innerHTML=s.tags.map(t=>`<span>${t}</span>`).join('');$('traits').innerHTML=s.traits.map(([symbol,key,value])=>`<div class="trait-row">${icon(symbol)}<dt>${key}</dt><dd>${value}</dd></div>`).join('');$('habitat-description').textContent=s.habitat;$('conservation').textContent=s.status;$('status-code').textContent=s.code;$('range-label').textContent=s.range.toUpperCase();$('closeup-description').textContent=s.closeup;$('closeup-art').innerHTML=details.has(s.id)?`<img src="${details.get(s.id)}" alt="Detail of ${s.name}">`:'';$('scene').setAttribute('aria-label',`Interactive 3D ${s.name}. Drag to rotate, arrow keys rotate, plus and minus zoom.`);updateSaved();renderTabs()}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===value));$('filter-label').textContent={all:'All species',featured:'Featured species',bird:'Birds',amphibian:'Amphibians',mammal:'Mammals',saved:'My collection'}[value];const list=filteredSpecies();if(list.length&&!list.some(({i})=>i===selected))selectSpecies(list[0].i);else renderTabs()}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));$('search').oninput=()=>{query=$('search').value;const list=filteredSpecies();if(list.length&&!list.some(({i})=>i===selected))selectSpecies(list[0].i);else renderTabs()};$('collection-button').onclick=()=>{query='';$('search').value='';setFilter('saved')};$('save').onclick=()=>{const s=species[selected];if(saved.has(s.id)){saved.delete(s.id);toast('Removed from your collection')}else{saved.add(s.id);toast(`${s.name} saved`)}try{localStorage.setItem('canopy-saved',JSON.stringify([...saved]))}catch{toast('Saved for this visit. Browser storage is unavailable.')}updateSaved();renderTabs()};$('featured-note').onclick=()=>{query='';$('search').value='';setFilter('featured');selectSpecies(0)};
const zoom=amount=>{targetDistance=T.MathUtils.clamp(targetDistance+amount,2.2,12)};$('zoom-in').onclick=()=>zoom(-.65);$('zoom-out').onclick=()=>zoom(.65);function resetView(){closeup=false;$('view-badge').hidden=true;targetDistance=species[selected].group==='bird'?10.8:7.5;yaw=species[selected].group==='bird'?-.15:species[selected].id==='frog'?-.5:-.12;pitch=0;orbit=false;$('orbit').setAttribute('aria-pressed',false)}$('reset').onclick=resetView;$('closeup').onclick=()=>{if(!sceneReady)return;closeup=true;targetDistance=3.1;pitch=.02;yaw=.05;$('view-badge').hidden=false;orbit=false;$('orbit').setAttribute('aria-pressed',false);if(innerWidth<=800)$('stage').scrollIntoView({behavior:paused?'instant':'smooth',block:'center'})};$('exit-closeup').onclick=resetView;$('rotate-left').onclick=()=>yaw-=.3;$('rotate-right').onclick=()=>yaw+=.3;$('orbit').onclick=()=>{orbit=!orbit;$('orbit').setAttribute('aria-pressed',orbit);$('orbit').setAttribute('aria-label',orbit?'Stop automatic 360-degree rotation':'Start automatic 360-degree rotation')};function updateMotion(){$('motion').setAttribute('aria-pressed',paused);$('motion').setAttribute('aria-label',paused?'Resume animal motion':'Pause animal motion');$('motion-label').textContent=paused?'Motion paused':'In motion';$('motion').querySelector('[data-icon]').innerHTML=icon(paused?'play':'pause')}$('motion').onclick=()=>{paused=!paused;updateMotion()};$('expand').onclick=()=>{const expanded=document.querySelector('.atlas').classList.toggle('expanded');$('expand').setAttribute('aria-pressed',expanded);$('expand').setAttribute('aria-label',expanded?'Restore species details':'Expand scene')};$('lighting').onclick=()=>{evening=!evening;document.querySelector('.atlas').classList.toggle('evening',evening);$('lighting').setAttribute('aria-pressed',evening);$('lighting').setAttribute('aria-label',evening?'Change to daylight lighting':'Change to evening lighting');if(keyLight){keyLight.color.set(evening?'#efd5aa':'#fff4d6');keyLight.intensity=evening?1.9:3.2;fillLight.intensity=evening?.9:1.7}};
$('about').onclick=()=>$('about-dialog').showModal();document.querySelector('.dialog-close').onclick=()=>$('about-dialog').close();$('previous-species').onclick=()=>selectSpecies((selected+species.length-1)%species.length);$('next-species').onclick=()=>selectSpecies((selected+1)%species.length);document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('search').focus()}});document.addEventListener('visibilitychange',()=>visible=!document.hidden);
let dragging=false,lastX=0,lastY=0;$('scene').onpointerdown=e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;$('scene').setPointerCapture(e.pointerId);orbit=false;$('orbit').setAttribute('aria-pressed',false)};$('scene').onpointermove=e=>{if(!dragging)return;yaw-=(e.clientX-lastX)*.008;pitch=T.MathUtils.clamp(pitch+(e.clientY-lastY)*.005,-.7,.75);lastX=e.clientX;lastY=e.clientY};$('scene').onpointerup=$('scene').onpointercancel=()=>dragging=false;$('scene').onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','='].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')yaw-=.15;if(e.key==='ArrowRight')yaw+=.15;if(e.key==='ArrowUp')pitch=Math.min(.75,pitch+.1);if(e.key==='ArrowDown')pitch=Math.max(-.7,pitch-.1);if(e.key==='+'||e.key==='=')zoom(-.6);if(e.key==='-')zoom(.6)};
try{initScene()}catch(error){$('render-error').hidden=false;console.warn('3D initialization unavailable',error)}selectSpecies(0);updateMotion();
